css:
.frame{position:absolute;inset:0;padding:var(--pad-top) var(--pad) var(--pad-bottom);display:flex;align-items:center;justify-content:center}
.paper{position:relative;width:78%;max-height:100%;background:#FBFAF6;color:#1d1c1a;padding:calc(var(--u)*6) calc(var(--u)*6) calc(var(--u)*7);display:flex;flex-direction:column;gap:calc(var(--u)*2.6);
  font-family:ui-monospace,'SFMono-Regular',Consolas,monospace;rotate:-2deg;box-shadow:0 calc(var(--u)*2) calc(var(--u)*6) rgba(0,0,0,.28)}
.paper::after{content:"";position:absolute;left:0;right:0;top:100%;height:calc(var(--u)*1.6);background:conic-gradient(from -45deg at 50% 0,#FBFAF6 90deg,transparent 0) 0 0/calc(var(--u)*3.2) 100% repeat-x}
.o-portrait .paper{width:86%}
.o-landscape .paper{width:52%;rotate:-1.5deg}
.top{display:flex;flex-direction:column;align-items:center;gap:calc(var(--u)*1.2);text-align:center;border-bottom:calc(var(--u)*.3) dashed #1d1c1a55;padding-bottom:calc(var(--u)*2.4)}
.top .logo img{height:calc(var(--u)*5);filter:grayscale(1) contrast(1.2)}
.top .wordmark{color:#1d1c1a;font-size:calc(var(--u)*3.4)}
.eyebrow{color:#1d1c1a99;font-family:inherit;letter-spacing:.2em;font-size:calc(var(--u)*2.3)}
.hbox{height:calc(var(--u)*15)}
.o-portrait .hbox{height:calc(var(--u)*20)}
.headline{width:100%;text-align:center;color:#1d1c1a}
.headline .hl{color:var(--accent)}
.list{list-style:none;padding:0;font-size:calc(var(--u)*2.8);gap:calc(var(--u)*1.3)}
.list li{display:flex;gap:1em;justify-content:space-between}
.list li::after{content:'✓';color:var(--accent);font-weight:700}
.list b{color:#1d1c1a}
.total{display:flex;justify-content:space-between;align-items:center;border-top:calc(var(--u)*.3) dashed #1d1c1a55;padding-top:calc(var(--u)*2.4);font-weight:700;font-size:calc(var(--u)*3);letter-spacing:.12em}
.sbox{width:45%;height:calc(var(--u)*11);justify-content:flex-end}
.stat-num{text-align:right;color:var(--accent)}
.foot{text-align:center;opacity:.55;font-size:calc(var(--u)*2)}
